import java.util.List;
import java.util.function.Predicate;

public class LambdaDemo {
    public static void main(String[] args) {
        var numbers = List.of(1, 2, 3, 4, 5, 6);

        // Old way: anonymous class
        numbers.stream()
            .filter(new Predicate<Integer>() {
                public boolean test(Integer n) {
                    return n % 2 == 0;
                }
            })
            .forEach(System.out::println);

        // Lambda way: concise and readable
        numbers.stream()
            .filter(n -> n % 2 == 0)  // Predicate<Integer> inferred
            .map(n -> n * n)          // Function<Integer, Integer> inferred
            .forEach(System.out::println);
    }
}

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class EffectivelyFinalDemo {
    private int instanceCounter = 0;  // Heap variable, no restriction

    public void processOrders(List<String> orders) {
        int localCounter = 0;  // Effectively final — never reassigned
        String prefix = "Order-";  // Effectively final

        // This works: localCounter and prefix are effectively final
        orders.forEach(order -> 
            System.out.println(prefix + order + " " + localCounter)
        );

        // Compile error: cannot reassign captured variable
        // localCounter++;  // Uncommenting this breaks effectively final

        // Instance variables CAN be modified
        orders.forEach(order -> instanceCounter++);  // This is fine

        // Workaround: use AtomicInteger for mutable local state
        var atomicCounter = new AtomicInteger(0);
        orders.forEach(order -> 
            System.out.println("Processed " + atomicCounter.incrementAndGet())
        );
    }
}

import java.util.List;

public class VariableAccessDemo {
    private int instanceCounter = 0;      // Instance variable
    private static int staticCounter = 0;  // Static variable

    public void processBatch(List<String> items) {
        int localValue = 10;  // Local variable — must be effectively final

        items.forEach(item -> {
            // Instance variable: can read and modify freely
            instanceCounter++;
            System.out.println("Instance count: " + instanceCounter);

            // Static variable: can read and modify freely
            staticCounter++;
            System.out.println("Static count: " + staticCounter);

            // Local variable: can read but NOT modify
            System.out.println("Local value: " + localValue);
            // localValue++;  // Compile error: must be effectively final

            // This reference: points to the enclosing instance
            System.out.println("This class: " + this.getClass().getSimpleName());
        });
    }
}

