public class ThisReferenceDemo {
    private String name = "Outer Instance";

    public void demonstrateLambda() {
        Runnable lambdaRunnable = () -> {
            // In lambda, 'this' refers to ThisReferenceDemo instance
            System.out.println("Lambda this: " + this.name);
            System.out.println("Lambda this class: " + this.getClass().getSimpleName());
            this.helperMethod();  // Can call enclosing class methods directly
        };
        lambdaRunnable.run();
    }

    public void demonstrateAnonymousClass() {
        Runnable anonymousRunnable = new Runnable() {
            @Override
            public void run() {
                // In anonymous class, 'this' refers to the Runnable instance
                System.out.println("Anonymous this class: " + this.getClass().getSimpleName());
                // System.out.println(this.name);  // Compile error: no 'name' field

                // Must use OuterClass.this to access enclosing instance
                System.out.println("Outer this: " + ThisReferenceDemo.this.name);
                ThisReferenceDemo.this.helperMethod();
            }
        };
        anonymousRunnable.run();
    }

    private void helperMethod() {
        System.out.println("Helper called");
    }
}

