import java.util.List;

public class LambdaVsNamedMethod {
    // complex / reused / testable rule -> a named method + method reference
    static boolean isEligible(String s) {
        return s.length() > 3 && s.startsWith("A") && !s.isBlank();
    }

    public static void main(String[] args) {
        var names = List.of("Al", "Ann", "Andy", "Bob");

        // short, single-use -> inline lambda
        names.stream().filter(s -> !s.isBlank()).forEach(System.out::println);

        // non-trivial rule -> named method reference
        names.stream().filter(LambdaVsNamedMethod::isEligible)
             .forEach(System.out::println);
    }
}
