import java.io.*;
import java.util.List;
import java.util.function.Function;

public class LambdaExceptionDemo {

    // Compile error: Function.apply() doesn't declare throws IOException
    // public void bad(List<String> paths) {
    //     paths.stream().map(path -> readFile(path)).toList();
    // }

    // Solution 1: Wrap checked exception in unchecked
    public List<String> wrapException(List<String> paths) {
        return paths.stream()
            .map(path -> {
                try {
                    return readFile(path);  // Throws IOException
                } catch (IOException e) {
                    throw new UncheckedIOException(e);  // Wrap as unchecked
                }
            })
            .toList();
    }

    // Solution 2: Custom functional interface
    @FunctionalInterface
    interface FunctionWithException<T, R, E extends Exception> {
        R apply(T t) throws E;
    }

    private String readFile(String path) throws IOException {
        return Files.readString(Path.of(path));
    }
}

import java.util.List;
import java.util.function.Predicate;

public class LambdaCompilationDemo {

    // Lambda version — compiled to invokedynamic + static method
    public List<String> filterWithLambda(List<String> items) {
        return items.stream()
            .filter(s -> s.length() > 3)  // Becomes private static boolean lambda$filterWithLambda$0(String s)
            .toList();
    }

    // Anonymous class version — compiled to MyClass$1.class file
    public List<String> filterWithAnonymous(List<String> items) {
        return items.stream()
            .filter(new Predicate<String>() {
                @Override
                public boolean test(String s) {
                    return s.length() > 3;
                }
            })  // Generates LambdaCompilationDemo$1.class
            .toList();
    }

    // After compilation, lambda version contains:
    // private static boolean lambda$filterWithLambda$0(String s) { return s.length() > 3; }
    // and an invokedynamic instruction to call LambdaMetafactory
}
